  AND blocks = $old$[{"type": "contract", "title": "הסכם השתייכות", "sub": "שנערך ונחתם", "rows": [{"label": "בין:", "value": "הקבוצה, הפועלת מטעם הקיבוץ ובאמצעות בית הילדים (להלן: ״הקבוצה״)"}, {"label": "לבין:", "value": "היחיד, קטין (להלן: ״הילד״)"}, {"label": "חתימת הילד:", "value": "[טביעת כף רגל של תינוק]", "img": "/assets/article/a05-footprint.webp"}, {"label": "תאריך:", "value": "גיל שישה שבועות"}, {"label": "מקום:", "value": "בית התינוקות"}, {"label": "בשם הקטין חתמו:", "value": "הוריו, חברי הקיבוץ"}, {"label": "בשם הקבוצה חתם:", "value": "הקיבוץ, באמצעות ועדת החינוך", "stamp": ["הקיבוץ", "ועדת החינוך"]}]}, {"type": "list", "ordered": true, "items": ["**הואיל** ולא טוב היות האדם לבדו, והאדם הוא יצור חברתי בבסיסו;", "**והואיל** וקבוצה נותנת לילד מוגנות, שייכות וכוח שאין לו לבדו;", "**והואיל** וקבוצה אינה יכולה להתקיים בלי פרטים שרואים עצמם חלק ממנה, ומחויבות הפרטים היא תנאי הכרחי לקיומה;", "**והואיל** וכל צד בהסכם מקבל משהו ומוותר על משהו;", "**והואיל** והקבוצה שומרת על תנאי ההסכם בכוחות גלויים וסמויים, וכוחות אלה לגיטימיים ונחוצים לקיומה;", "**והואיל** וככל שהילד תלוי יותר בקבוצה, כך היא יכולה לדרוש ממנו יותר;", "**והואיל** והילד נולד אל הקבוצה כפי שנולדים אל משפחה, והיא נתונה לו ואינה נבחרת;", "**והואיל** והקבוצה נושאת בכל תחומי חיי הילד, ואין לו קבוצה אחרת זולתה;", "**והואיל** ואף צד אינו יכול לסיים את ההסכם: הילד אינו יכול לצאת מן הקבוצה, והקבוצה אינה יכולה להוציאו ממנה, ולפיכך כל צד חייב לשאת את השני, יהא המחיר אשר יהא;"]}, {"type": "text", "body": "**לפיכך הוצהר, הותנה והוסכם בין הצדדים כדלקמן:**"}, {"type": "table", "head": ["מונח", "פירוש"], "rows": [["״קבוצה״", "קבוצת ילדים בני אותו שנתון, שנקבעה בידי הקיבוץ ופועלת בבית הילדים, על מטפלותיה ומחנכותיה"], ["״יחיד״", "פרט אחד מבין חברי הקבוצה. בהסכם זה: הילד"], ["״הסכם״", "החוזה הלא כתוב בין היחיד לקבוצה: מה כל צד נותן, מקבל ומוותר עליו"], ["״סיבולת גמישות״", "הטווח שבתוכו צד מוכן להתגמש בלי שההסכם יישבר. לקבוצה: כמה שונות היא נושאת. ליחיד: על כמה מעצמו הוא מוכן לוותר"], ["״כוח גלוי״", "כלל, החלטה, הצבעה, תפקיד, תורנות, פרס או עונש שנאמרים במפורש"], ["״כוח סמוי״", "נורמה שלא נאמרה, מבט, צחוק, שתיקה, כינוי, דירוג, ומי שמוצג כדוגמה. כולל נורמה שהופנמה עד שאינה צריכה עוד את האחרים"], ["״חופש היחיד״", "התחום שבו היחיד מחליט בעצמו, וכוח הקבוצה אינו מגיע אליו: ייחודיות, שליטה, בחירה, אוטונומיה"], ["״שונות״", "כל מה שבו היחיד אינו כמו שאר ילדי הקבוצה"], ["״יציאה״", "סיום ההשתייכות לקבוצה, ביוזמת היחיד או ביוזמת הקבוצה. בהסכם זה: אינה עומדת לאף אחד מן הצדדים עד תום ההתקשרות. בתומה ההשתייכות אינה מחייבת עוד, והיחיד נתון לחוקי הקיבוץ. ראו סעיף 14"], ["״צד שלישי״", "מי שאינו צד להסכם, ובכלל זה הורי הילד"]]}, {"type": "subheading", "text": "פרק א׳: הענקות שלא בתמורה"}, {"type": "text", "body": "**א. כללי**\n\nא.1 ההענקות המפורטות בפרק זה אינן מותנות בדבר, למעט היוולדות הילד לחברי הקיבוץ. תנאי זה התקיים במלואו ביום לידתו.\n\nא.2 הילד לא יידרש ליתן בעד הענקות אלה כל תמורה. אין באמור כדי לגרוע מתקוותה של הקבוצה כי בבוא העת יגדל הילד לחבר קיבוץ בוגר, פעיל ושמח, השותף לחיי הקהילה ולערכיה."}, {"type": "text", "body": "**ב. טבע**\n\nהקבוצה תעניק לילד מרחבי טבע פתוחים, לרבות: השדות שלמטה, ״מגיעים עד לקו של השמים״[^1]; האפלולית שמתחת לשקמים, הפירות המעוכים בדרך והברחשים; ״השיחים הצפופים של הקידה השעירה והסירה הקוצנית״ שבדרך חזרה מן הסכר, ברגליים יחפות, שאיכשהו, כפתורי החולות אינם נתקעים בהן; וזר ״תורמוסים כחולים בוהקים״ לפינת הטבע."}, {"type": "text", "body": "**ג. חגים וטקסים**\n\nהקבוצה תעניק לילד חגים וטקסים, לרבות: מקום ליד השולחן הארוך בליל הסדר, ואם המקום ״בקצה הרחוק״, יקבל הילד כיסא לעמוד עליו ויוכל לראות את הבמה; חלונות מוארים של צלופן צבעוני, ושלוש־עשרה חנוכיות במקום שתים־עשרה; ועלייה במִיכָלְזוֹן ״לתוך הענפים של האזדרכת״, לקטוף שקית ממתקים בְּיוֹמָיֶלֶד."}, {"type": "text", "body": "**ד. השכלה**\n\nהקבוצה תעניק לילד חינוך והשכלה, לרבות: אדמת לס, ״אבקה דקה וגרגירית״, שבמגע עם מים הופכת אטומה; גרעין של מנגו, ובתוכו עובר מקופל; ובוקר אחד שבו יקום לפני השמש, ישמע את הציפורים מתעוררות יחד, יכין שער לנושא ״הבוקר״, ויחשוב שראה בריאה."}, {"type": "text", "body": "**ה. חברות לחיים**\n\nהקבוצה תעניק לילד חברים לחיים, שאיתם ״אני נרדמת ומתעוררת, איתם אני חיה — מהבֵּיתִּינוֹקוֹת עד עכשיו וגם אחר כך״. בבגרותו יישארו חברי הקבוצה יקרים ללבו, לא כולם, ולא אלה שיחסיו עמם היו פוגעניים. כמו במשפחה, ולעתים כמו במשפחה רחוקה, יהיו אותם חברים יקרים לו, גם אם לא יהיו מעורבים בחייו. ״׳אני אבוא לבקר,׳ אני לוחשת. את זה אני כן יודעת, את זה אני אומרת.״"}, {"type": "text", "body": "**ו. גאוות יחידה**\n\nהקבוצה תעניק לילד חלק בהוד הקיבוץ, לרבות: להיות פועלים, ״הכבוד הכי גדול שיש״; נסיעה בקבינה של הקטפת, גבוה מעל שורות הכותנה, בקיבוץ שיש לו ״הכי הרבה קטפות בכל הקיבוצים באזור״; בָּלָה שנשארת בשדה מכוסה בברזנט ״עם השם של הקיבוץ שלנו״; מנגואים ש״הם הכי טובים שיש״; מדריכת שחייה מנבחרת ישראל, ש״באים אלינו, מקיבוצים אחרים, ללמוד ממנה״; ילד שרץ למרפאה עם האצבע של חברו, כי ״רותם הוא הקיבוץ״; והקומביין הענק של השלחין, שקוצר בשבועות מול הקהל שורה אחרונה של חיטה, ומוריד על הילדים ״גשם של סוכריות מעורבבות בגרעיני חיטה״ — ב״ביתנו הקיבוצי שהוא הכי יפה בעולם״."}, {"type": "subheading", "text": "פרק ב׳: הענקות ותמורתן"}, {"type": "text", "body": "**1. התמורה**\n\n1.0 מטרת הסכם זה היא לגדל את הילד לחבר קיבוץ בוגר, פעיל ושמח, השותף לחיי הקהילה ולערכיה, לרבות: הרשות לגדול, וכש״נהיה מוֹסָדְנִיקִים, נצטרף גם אנחנו לאחד הענפים ונקבל בגדי עבודה כחולים״; והזכות להקים ״לי בית בביתנו הקיבוצי ואקים משפחה עם משפחותיה״.\n\n1.1 הקבוצה תעניק לילד את המפורט בסעיפים 2 עד 12.\n\n1.2 בתמורה, יקבל על עצמו הילד את מחירה של כל הענקה, כמפורט בסעיפים 2 עד 12.\n\n1.3 ילד שלא יוותר כאמור יהיה צפוי לסנקציות, גלויות וסמויות. ילד שיוותר כאמור יזכה לתגמולים. אין באמור כדי לגרוע מן ההענקות המפורטות בפרק א׳, אשר יינתנו לילד בכל מקרה."}, {"type": "text", "body": "**2. תחילת ההתקשרות והרכב הקבוצה**\n\n2.1 תנאי הסכם זה נקבעו בטרם נולד הילד, והם חלים על כל ילד שייולד לחברי הקיבוץ. ההסכם נכנס לתוקף בהעברת הילד לבית התינוקות, בגיל שישה שבועות. הסכמת הילד אינה נדרשת.\n\n2.2 הקבוצה תעניק לילד קבוצת שווים קבועה למשך שנות ילדותו, לרבות: ילדים ״מאותה שישייה, מאותו בֵּיתֶלָדִים״; וחברה אחת לפחות, ש״יודעת דברים שעמליה ורות׳קה לא יודעות עלי״, ושאיתה אפשר להבין ״בלי מילים את אותם דברים שאין להם שם״.\n\n2.3 בתמורה, יוותר הילד על בחירת חברי הקבוצה. ״לא בוחרים לאיזו שישייה להיוולד״, והרכב הקבוצה ייקבע על פי הגורל, לפי מי שנולד עם הילד באותו שנתון. אותם ילדים, שלא בחר בהם, יעמדו איתו מתחת למים בטוש, כי ״לא בוחרים עם מי מתקלחים״, והם יראו את הסדין הרטוב. ״רות׳קה ממילא תראה מחר את המצעים הרטובים בשַׂקְבִיסָה. וגם כולנו.״"}, {"type": "text", "body": "**3. חופש**\n\n3.1 הקבוצה תעניק לילד חופש: השתוללויות, צחוקים ושטויות של ילדים, לרבות: מדרכות ודשאים, כי ״המדרכות שלנו. כל הדשאים פתוחים, אין גדרות״; התגנבות בלילה, בפיג'מות, וקפיצה ״לתוך השיחים כשעובר מבוגר״; פתח בגדר האחורית של הבריכה, ש״כולם יודעים איפה הוא, אבל זה סוד״; כתמים של תותים על כפות הידיים, ש״יסגירו אותנו כשנחזור, אבל זה עדיין שווה את זה״; ורות׳קה ש״מכירה בדיוק מה אנחנו מסוגלים לעשות ולא מפחדת לתת לנו״.\n\n3.2 בתמורה, יוותר הילד על חופש שלא ניתן לו ברשות, ויקבל על עצמו את גבולות הקבוצה, לרבות: לצאת לדרך ״כמו סוסים פראיים רק כשרות׳קה אמרה שאפשר״; לעשות ״הכול, כל עוד אנחנו לא נכנסים לגינות של חברים״; ולשמור על המשותף, כי ״הנוי הוא של הקיבוץ והקיבוץ זה אנחנו. אם נקלקל את המכסים של הממטרות אנחנו מקלקלים לנו״."}, {"type": "text", "body": "**4. סיפוק צרכים**\n\n4.1 הקבוצה תספק לילד את כל צרכיו; הוא אינו צריך לבקש, שכן ״סוציאליזם זה שהקבוצה דואגת לכל החברים שלה שיהיה להם מה שצריך״, לרבות: זוג אופניים, כי ״לכל ילד או חבר מגיע זוג אופניים״; קמח וסוכר בחלוקה, ש״לא צריך לרשום, לא צריך לבקש״; בגדים, ״ערֵמות ערֵמות. לאף ילד לא יחסר״; ומה שילד אחד צריך יותר מאחרים, כמו שניצל, צ'יפס ו״דני״ למאור, כי ״הסוציאליזם דואג שיהיה לו״.\n\n4.2 בתמורה, יוותר הילד על הזכות להגדיר בעצמו מהם צרכיו. צורך שלא הוכר בידי הקבוצה לא ייחשב צורך, לרבות: שעות רוּחָה, הניתנות רק למי שמתקשה בלימודים, גם אם ילדה שטובה בחשבון רוצה בהן כדי שרוּחָה ״תדבר איתי לאט ובשקט״; לבקש ״שיחזירו אחורה את הסרט״, כדי לראות את אמא של במבי בפעם האחרונה ו״שאוכל להתכונן לירייה״, אבל ״לא מחזירים אחורה בשביל ילדה אחת״; לִילוֹ, דובי צהוב עם מעיל משבצות ירוק, שליווה את הילד במיטה, ו״ההשכבות נעשו יותר קשות אחרי שהוא נעלם״; מבט אחרון מאבא, שהילד מחכה לו מבעד לתריסים ״כמו בכל ערב — אולי הפעם יסתובב?״."}, {"type": "text", "body": "**5. הגנה**\n\n5.1 חברי הקיבוץ ערבים זה לזה, וערבותם חלה גם על ילדיהם. כל חבר קיבוץ יחוש לעזרת הילד בעת סכנה, ואף ילד לא יישאר לבדו בצרתו. ״אנחנו מסתדרים לבד, בנדנדות או במגרש. עד שקורה לנו משהו. כשניר צעק, כולם הגיעו.״ ערבות זו תחול בכל שעות היממה, לרבות בלילה, שבו תשב מול השמרטף אמו של ילד אחר, ו״כל בכי מהפעוטונים או מהבַּתֶיֶלָדִים — יגיע אליה. היא תעזוב הכול ותרוץ אליהם.״\n\n5.2 בתמורה, יקבל הילד את סמכותו של כל חבר קיבוץ עליו, שכן ההגנה וההשגחה אחת הן: מי שירוץ להציל את הילד הוא שיחזיר אותו אל הסדר כשיחרוג ממנו. כל חבר קיבוץ רשאי לעצור את הילד ולהחזירו למקומו, לרבות בבריחה מבית הילדים בלילה, גם כשהילד בורח אל אמו. ״על החוקים של כולם מותר לכולם להגיד, כי כולם אחראים.״"}, {"type": "text", "body": "**6. שייכות**\n\n6.1 הקבוצה תעניק לילד שם ו״מהיום אנחנו קבוצת 'ארזים', לפני ההצבעה לא יכולנו להגיד מי אנחנו. עכשיו אנחנו יכולים. אנחנו 'ארזים'״; צבע של מדבקת הסימון בקומונה ״אנחנו, 'ארזים', סגול״; ו**אנחנו**, כינוי גוף ברבים, לדבר בו גם כשהוא יחיד.\n\n6.2 בתמורה, יקבל הילד את הכרעת הרוב, וימנע מלעשות מה שאחרים אינם עושים. הכרעת הרוב תחייב את כל חברי הקבוצה, כפי ש״עמליה הסבירה שהמיעוט צריך לקבל את דעת הרוב״, ואת עלבונו יישא המיעוט לבדו. הילד לא יימנע. ״אין רשות להימנע כי קבוצה צריכה שישתתפו בה כדי להיות קבוצה״, ומשהשתתף, תהיה דעתו דעת הקבוצה, ו״כל מי שאומר אחרת ממפ\"ם — טועה.״"}, {"type": "text", "body": "**7. שוויון**\n\n7.1 כל חברי הקבוצה זכאים לאותו דבר, באותה מידה. הקבוצה תשאף להעניק לכולם שווה בשווה, ולא יהיה ילד שקיבל פחות מחברו. כל ילד יקבל ״מכנסי שבת אחד וחולצת שבת אחת חדשים חדשים״, כי ״לכל אחד מגיע״, ואת שקית הצ'יפס הקר מארוחת הלילה של השומרים יחלק הילד שהוריו שמרו אחד אחד, כך ש״ביום טוב, כשהשומרים משאירים שקית גדולה, כל אחד מקבל שלושה צ'יפסים״.\n\n7.2 בתמורה, יקבל הילד את ההנחה שכולם זכאים לאותו דבר משום שכולם אותו דבר, ו״בגלל שכולם צריכים אותו דבר — כולם מקבלים אותו דבר״. לפיכך יוותר על מה שמעבר לשווה, לרבות זמן, תשומת לב ורשות דיבור. ״עמליה אומרת שעיניים גדולות זה לא טוב״, והילד ילך בקצב של כולם, כי ״ברוב הדברים עדיף להיות בזמן של כולם״. ילד היודע את התשובה ימתין ״עד שמספיק אחרים יקבלו גם״; ילד המוזג ״צריך למזוג לעצמו אחרון״; וגם במקום שאין בו מי שסופר, ״אף אחד לא לוקח יותר מאחד, כי אז לא יישאר לכולם״."}, {"type": "text", "body": "**8. ייחוד**\n\n8.1 יום אחד בשנה, ביום הולדתו, יוכר הילד כיחיד. ״כל השנה כולנו אותו דבר. אין כמעט משהו שבו אנחנו מיוחדים לבד.״ אבל ביום זה ״כל אחד מאיתנו הוא אחד״, והילד יקום בבוקר ״ילדה אחת, לא אחת מתוך שלושה־עשר״.\n\n8.2 בתמורה, יחלוק הילד את הבמבה, הביסלי גריל, העדשים, סוכריות הטופי והשוקולד פרה עם כל חברי הקבוצה. ״הממתקים הם לכבודי, אבל הם לא שלי״."}, {"type": "text", "body": "**9. דימוי עצמי**\n\n9.1 הקבוצה תהיה לילד מראה, ותשקף לו מי הוא. בדרכים גלויות וסמויות תלמד אותו מתי הוא ילד טוב ומתי אינו. המראות יוצבו סביב הילד בכל שעות היממה, למעט בין ארבע בהקמה לשמונה בהשכבה. הן ישקפו לו מתי הוא ילד טוב, כשכולם ״מקשיבים לניר ומסתכלים על רותם, שנראה פתאום אחרת. גיבור.״, ומתי אינו, כי ״כולנו ב'ארזים' יודעים את הטעויות של כולנו. את מי שיש לו הרבה טעויות אנחנו מחשיבים פחות.״ הילד ייקח חלק במראות שהקבוצה מציבה לחבריו, ויעמוד בהן כעד שקוף גם כש״נעמה חוטפת עכשיו, לא אני. אבל אני לא רוצה להיות כאן.״ כך יהיה העד גם מראה לעצמו, ו״אנחנו רואים לְעמליה. אנחנו רואים לְנעמה. ואנחנו גם רואים לנו, איך אנחנו שותקים.״\n\n9.2 בתמורה, יסכים הילד כי כך ראוי שיהיה: כי הקבוצה היא שמשקפת לו מתי הוא ילד טוב ומתי אינו. במקרה של קונפליקט, כשדימויו העצמי אינו תואם את דימויו בעיני הקבוצה, תהיה דעת הקבוצה חזקה עליו. ״אולי לזה עמליה מתכוונת כשהיא אומרת שאני חצופה.״ ״העיניים הגדולות שלי זאת חמדנות.״ כך יאמץ הילד את שפתה כשפתו."}, {"type": "text", "body": "**10. מקום ורכוש**\n\n10.1 הקבוצה תקצה לילד מקום קבוע: מיטה, כיסא ליד שולחן האוכל וליד השולחן בכיתה, מתלה מגבת עם מדבקת שמו, כוס למברשת ולמשחת השיניים, ותספק לו ביגוד ומצעים. הילד לא יידרש לדאוג לרכושו, ותמיד יהיה לו המקום הקבוע שלו, וארונית ש״היא רק שלנו. בעצם לא הארונית, אבל מה שבתוכה.״\n\n10.2 בתמורה, יוותר הילד על בעלות. המקומות והחפצים מוקצים לו לשימוש בלבד, ויוחלפו מעת לעת. הזיקה לחפץ נמדדת בשימוש בו, וחולצה ״היא שלי כל זמן שהיא מתאימה לי״, ואין לילד סיבה לרצות בה לפני שמידתה מתאימה לו או כשהיא כבר קטנה עליו."}, {"type": "text", "body": "**11. אחריות הורית**\n\n11.1 בית הילדים יישא באחריות ההורית לילד, והצוות החינוכי (המחנכת, המטפלת, המתנדבת ושומרת הלילה) ימלאו כלפיו את הפונקציות ההוריות בכל שעות היממה, למעט בין ארבע בהקמה לבין שמונה בהשכבה. המטפלות ישמרו עליו ועל חבריו ״כשאנחנו מתעוררים, אוכלים, מתקלחים ונרדמים״, ישימו ״יוד ופולידין על הברכיים״ וישירו לו בכל ערב ״דוגית״, ושומרת הלילה תבוא אל מיטתו בלילה. הוריו, היודעים ״שאנחנו שמורים כאן״, יהיו פנויים מעול הטיפול היומיומי, ובשעות המפגש יקבל מהם הילד את אהבתם בלבד.\n\n11.2 בתמורה, יקבל הילד כי הפונקציות ההוריות הופקעו מהוריו והועברו לבית הילדים. הוא ישהה עם הוריו בין השעות 16:00 ל-19:45. לא הוריו הם שיעירו אותו בבוקר, לא הם שירחצו אותו, לא הם שישימו אוכל בצלחתו למעט ארוחת ערב, לא הם שיהיו איתו עד שיירדם ולא הם שיבואו אל מיטתו בלילה."}, {"type": "text", "body": "**12. שפה פרטית**\n\n12.1 הקבוצה תקיים יחסים פנימיים בין חבריה ובין אנשי הצוות שלה, ובהם מעמדות, הרגלים ונורמות הידועים לחבריה. הקבוצה תעניק לחבריה שפה וקודים משלהם, המובנים רק להם, והיגיון פנימי שאינו נגלה למי שבא מבחוץ. חבר שיעצור את הילדים על אופניהם בכביש שמחוץ לקיבוץ וישאל בהשתאות ״לאן אתם?״ ייענה בשתיקה. ״הוא לא מהבֵּיתֶלָדִים. הוא לא יודע שזה הגיוני.״\n\n12.2 בתמורה, יבין הילד כי בית הילדים ובית ההורים הם שני עולמות, ומה שמתרחש בבית הילדים שייך לבית הילדים. בין שני העולמות ינוע הילד לבדו, והוא שיבחר מה לספר. את מה שאפשר לספר, יספר. את מה שרק מי שבפנים יודע, ורק מי שבפנים יכול להבין, ישאיר לרוב בבית הילדים. אין זה סוד ואין זה איסור. מי שאינו מבפנים לא תמיד יבין, ומגיל צעיר יֵדע הילד מתי אין צורך ואין טעם לנסות. ההורים יבקרו בבית הילדים כאורחים, גם כשהם עושים בו שיבוץ, ו״דברים שאנחנו לא רוצים לעשות לא נספר להם אם הם לא יודעים לשאול.״ הורים שידעו לשאול, יקבלו לעתים תשובה."}, {"type": "text", "body": "**13. חזקת ההסכם**\n\n13.1 חזקה כי תנאי הסכם זה מיטיבים עם כל ילד. ראיה לכך הם הילדים שההסכם עולה יפה בעבורם, ש״לא בורחים״ ו״מצליחים לא לאסוף נקודות רעות״. לפיכך לא נקבע בהסכם הליך לשינויו או לערעור עליו.\n\n13.2 היה המחיר הנגבה מן הילד לפי הסכם זה גבוה מכפי יכולתו לשלם, ולא היה הילד מאושר בתנאיו, לא ייחשב הדבר כפגם בהסכם, ואין בו כדי לגרוע מתוקפו של ההסכם כלפיו. מקור הקושי יימצא בילד עצמו, ועל ילד כזה יאמרו ״היא לא מהמחזיקים״, ו״ככה היא״."}, {"type": "text", "body": "**14. סיום ההתקשרות**\n\n14.1 ההתקשרות תסתיים לאחר כשמונה־עשרה שנים, בתום שתים־עשרה שנות לימוד, או במועד גיוסו של הילד לשירות צבאי.\n\n14.2 על אף האמור בסעיף 14.1, ההתקשרות תסתיים אם הורי הילד יעזבו את הקיבוץ. לעניין זה, הסכמת הילד אינה נדרשת.\n\n14.3 עם השגת מטרת הסכם זה, כאמור בסעיף 1.0 (לגדל את הילד לחבר קיבוץ בוגר, פעיל ושמח, השותף לחיי הקהילה ולערכיה), תתפרק הקבוצה. סדר היום המשותף יבוטל. חברי הקבוצה יעברו לקבוצה הגדולה, היא הקיבוץ, וקבוצת בית הילדים תחדל להתקיים. מן הקבוצה תיוותר זיקה של רגש וזיכרון בין מי שהיו חבריה, בלא חובה ובלא חזקה."}, {"type": "text", "body": "**15. כללי**\n\n15.1 תנאי הסכם זה אינם כתובים. חזקה על הצדדים שהם יודעים אותם."}, {"type": "divider"}, {"type": "text", "body": "איפה מתקיים חוזה שאתה גדל בתוכו? חוזה שמעולם לא נכתב. שמעולם לא נקרא.\n\nהיחיד והקבוצה. היכן שנמצאים שניים אלה — קיים גם חוזה. לעתים הוא מובן מאליו כל כך, עד שאי אפשר לשאול עליו.\n\nארבעת המאמרים הקודמים עסקו גם הם בחוזה. אחר. חוזה בין הילד לבין המבוגרים המגדלים אותו. במאמר הזה ביקשתי להסב את המבט אל הקבוצה. והסבת המבט פוגעת בבטן הרכה. המאמר הזה שונה מקודמיו —\n\n**דרך הטבע.** כשבתינוק ובמבוגר מטפל עסקינן, יש לזה דרך טבע. יכולנו לשרטט מציאות נורמטיבית ולבחון את בית הילדים למולה. אך מה לגבי קבוצת בית הילדים? קבוצה שאין דומות לה בהיסטוריית עולם החינוך והטיפול. לקבוצה כזאת אין דרך טבע, אז איך נבין אותה, את הדינמיקות יוצאות הדופן שפעלו בה, איך נתבונן בה?\n\n**חֶסֶר מול עודף.** במאמרים הקודמים מיקדנו מבט אל מה שלא היה: הידיים שלא באו בלילה, הדמעות שחיכו. במאמר הזה לא כך הוא. החוזה בין היחיד לקבוצה פעל בעוצמה וללא הפסקה עד כדי חודרנות. והבטן מתכווצת דווקא בגלל שלא מדובר בְּחֶסֶר, אלא בחוסר־ישע אל מול נוכחות גדולה. גדולה כל כך, גדולה כל כך, גדולה כל כך...\n\n**פנים.** המאמרים הקודמים חיפשו דמויות — לרות׳קה היו פנים, ולשומרת הלילה היה שם. השחקנים היו ברורים — אמא, אבא, ילד. המאמר הזה מביא לקידמת הבמה ישות ללא פנים. הקבוצה היא כולם; הקבוצה היא אני. איפה היא נגמרת ואני מתחיל? וכשאני כבר לא חלק ממנה, איפה אני מתחיל?\n\n**סביל מול פעיל.** בארבעת המאמרים הקודמים עמד הילד במקום הסביל. המבוגר העניק, או לא העניק, והילד התמודד עם החסר. במאמר הזה הילד כבר אינו רק הסביל. המאמר הזה נוגע במציאות קונפליקטואלית שפגשנו כל יום — לרגעים להיות יחיד מול כוחות הקבוצה, וברגעים אחרים להיות הקבוצה ולהפעיל את כוחנו על יחיד אחר. מה שכאב לנו בא מן הקבוצה, ואנחנו חלק ממנה.\n\nלא טוב היות האדם לבדו. רובנו שייכים לקבוצה, ולרוב ליותר מאחת. השייכות הזאת היא רקמה עדינה של איזונים ושיווי־משקל, של כוחות גלויים וכוחות סמויים; דינמיקות עשירות ועמוקות, עולם ומלואו. כך היה גם בית הילדים.\n\nהמאמר הזה הוא מבוא לשלושת המאמרים הבאים שיעסקו בקבוצה שבתוכה חיינו עשרים שעות ביממה: בצורות ההסתגלות השונות שבהן התמודדנו עם החוזה ועם הכוחות שפעלו בקבוצה; קבוצה שאנחנו היינו היא, והיא הייתה אנחנו."}, {"type": "sidenotes", "items": [{"label": "", "body": "כל הציטוטים בהסכם זה לקוחים מתוך הספר ״עיניים גדולות זה לא טוב״."}]}]$old$::jsonb;
